import "core-js/modules/es6.number.constructor";
import { projectmanagerList } from '@/api/assets/projectManage';
export default {
  props: {
    placeholder: {
      type: String
    },
    type: {
      type: String
    },
    disabled: {
      type: Boolean
    },
    value: {
      type: [String, Number, Array],
      default: ""
    }
  },
  watch: {
    value: function value(val) {
      this.myValue = val;
      this.$emit("input", val);
    }
  },
  data: function data() {
    return {
      isShow: false,
      searchForm: {
        current: 1,
        size: 20
      },
      // 表格
      tableData: [{
        eprNum: 2023
      }, {
        eprNum: 220
      }],
      tableHeight: '550px',
      tableLoading: false,
      total: 0,
      selectList: [],
      list: [],
      myValue: this.value
    };
  },
  created: function created() {
    this.getList();
  },
  methods: {
    select: function select(val) {
      this.selectList = val;
    },
    handleClick: function handleClick() {
      if (this.disabled) {
        return;
      }
      this.isShow = true;
      this.getList();
    },
    getList: function getList() {
      var _this = this;
      this.tableLoading = true;
      this.searchForm.projectUnitCode = this.$store.state.user.userDetail.erpUnitCode;
      projectmanagerList(this.searchForm).then(function (res) {
        _this.tableData = res.data.records;
        _this.total = res.data.total;
        _this.tableLoading = false;
      }).catch(function () {
        _this.tableLoading = false;
      });
    },
    handleSubmit: function handleSubmit() {
      if (this.selectList.length != 1) {
        this.$message.warning("请选择一条数据!");
        return;
      }
      if (this.type == 'wbsElement') {
        this.$emit('input', this.selectList[0].wbsCode);
      } else if (this.type == 'wbsProject') {
        this.$emit('input', this.selectList[0].wbsName);
      }
      this.$emit("change", this.selectList[0], this.type);
      this.isShow = false;
    },
    handleSEmpty: function handleSEmpty() {
      this.$emit('input', undefined);
      this.$emit("change", {}, this.type);
      this.isShow = false;
    },
    // 查询
    handleQuery: function handleQuery() {
      this.searchForm.current = 1;
      this.getList();
    },
    // 重置
    searchReset: function searchReset() {
      this.searchForm = {
        current: 1,
        size: 20
      };
      this.getList();
    },
    handleSave: function handleSave(row) {
      //保存
      if (this.type == 'wbsElement') {
        this.$emit('input', row.wbsCode);
      } else if (this.type == 'wbsProject') {
        this.$emit('input', row.wbsName);
      }
      this.$emit("change", row, this.type);
      this.isShow = false;
    }
  }
};
